look.customCSS:
/* ───── 月下星路 · 第一批 ───── */
/* 底色：褪色的米灰，颗粒、暗角、零星糖果色星星；一轮太近太亮的月亮压在右上 */
[data-wk="chat"]{position:relative !important;background:url("data:image/svg+xml;base64,") center bottom/100% 30% no-repeat,radial-gradient(circle at 80% 18%,rgba(255,252,235,.9) 0 70px,rgba(255,252,240,.5) 90px,transparent 220px),url("data:image/svg+xml;base64,") 0 0/240px 300px,linear-gradient(180deg,#F6F5F0 0%,#ECEEEC 55%,#E3E8EA 100%) !important}
/* 一张太近的月亮脸：闭眼笑着，隔一阵睁一下眼 */
[data-wk="chat"]::before{content:"" !important;position:absolute !important;right:-40px !important;top:90px !important;width:220px !important;height:220px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;filter:drop-shadow(0 0 40px rgba(255,250,232,.9)) !important;opacity:.85 !important;pointer-events:none !important;z-index:0 !important}
[data-wk="chat"]::after{content:"" !important;position:absolute !important;right:-40px !important;top:90px !important;width:220px !important;height:220px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;opacity:0 !important;pointer-events:none !important;z-index:0 !important;animation:mpBlink 9s steps(1) infinite !important}
@keyframes mpBlink{0%,88%{opacity:0}89%,93%{opacity:.85}94%,100%{opacity:0}}
/* 底下一片透视的粉白格子地板，一直铺到看不见的地方 */
[data-wk="body"]::after{content:none !important}
[data-wk="body"] > *{position:relative !important;z-index:1 !important}
[data-wk="body"]{background:transparent !important}

/* 顶栏：一层旧玻璃，底边一道发虚的月光线 */
[data-wk="chathead"]{background:rgba(255,255,255,.55) !important;backdrop-filter:blur(8px) !important;-webkit-backdrop-filter:blur(6px) !important;border-bottom:none !important;box-shadow:0 1px 0 #fff,0 4px 18px rgba(200,212,218,.4) !important}
[data-wk="headink"],[data-wk="headink"] *{color:#4A4E52 !important;letter-spacing:.12em !important}
[data-wk="headdim"],[data-wk="headname"] > div:last-child{color:#9AA0A4 !important}
[data-wk="chatback"] svg{stroke:#4A4E52 !important}
[data-wk="sameroom"],[data-wk="chatmore"]{width:26px !important;min-width:26px !important;height:26px !important;flex-shrink:0 !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;border-radius:0 !important;background-color:transparent !important}
[data-wk="sameroom"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;margin-left:auto !important}
[data-wk="chatmore"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;margin-left:4px !important}
[data-wk="chatmore"] *,[data-wk="sameroom"] *{opacity:0 !important}
[data-wk="chat"] [data-wk="chathead"] [data-wk="headme"]{display:inline-flex !important;margin-left:-6px !important}
[data-wk="chathead"] [data-wk="headme"] > *,[data-wk="chathead"] [data-wk="headme"] img,[data-wk="chathead"] [data-wk="avatar"]{width:32px !important;height:32px !important;min-width:32px !important;aspect-ratio:1 !important;border-radius:50% !important;box-shadow:0 0 0 2px #FFFCEB,0 0 10px 3px rgba(245,239,210,.55) !important}
[data-wk="chathead"] [data-wk="headname"]{flex:1 1 auto !important;min-width:84px !important;margin-left:6px !important}

/* 头像：一轮月亮——月光一圈，外面一圈偏开的重影 */
button[data-wk="avatar"],span[data-wk="avatar"],button[data-wk="avatar"] *,span[data-wk="avatar"] *,[data-wk="msg"] [data-wk="avatar"],[data-wk="cardrow"] [data-wk="avatar"],[data-wk="rpsingle"] [data-wk="avatar"]{border-radius:50% !important}
[data-wk="body"] button[data-wk="avatar"],[data-wk="body"] span[data-wk="avatar"]:not([data-halo]){box-shadow:0 0 0 3px #fff,0 0 18px 5px rgba(255,240,214,.9),6px -4px 0 5px rgba(190,205,212,.4) !important}
[data-wk="body"] [data-wk="avatar"] > img[data-wk="avatar"]{box-shadow:none !important}

/* 气泡：他是一团月光雾（边缘糊开、自己发光）；我是一块旧电视屏（深色、细细一道发光边）；底下排队跟着一串糖果色星星 */
[data-wk="bubble"][data-kind="text"]{position:relative !important;overflow:visible !important;border-radius:14px !important;line-height:1.65 !important;letter-spacing:.08em !important;margin-bottom:10px !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]{background:radial-gradient(ellipse at 50% 40%,#FFFDF0,#FFFCEB 70%) !important;color:#4A4E52 !important;box-shadow:inset 0 0 0 1.5px #F2E6B8,0 0 22px 8px rgba(255,240,200,.9) !important;padding:11px 18px !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]{background:linear-gradient(180deg,rgba(226,234,238,.95),rgba(208,219,225,.95)) !important;color:#3E4A52 !important;box-shadow:inset 0 0 0 1.5px #fff,0 0 16px 4px rgba(190,214,224,.7) !important;padding:11px 18px !important}
[data-wk="bubble"][data-kind="text"]::after{content:"" !important;position:absolute !important;left:12px !important;right:12px !important;bottom:-12px !important;height:14px !important;background:url("data:image/svg+xml;base64,") 0 0/120px 16px repeat-x !important;filter:drop-shadow(0 0 3px rgba(255,255,255,.9)) !important;pointer-events:none !important;animation:mpDrift 7s ease-in-out infinite !important}
@keyframes mpDrift{0%,100%{transform:translateX(0)}50%{transform:translateX(5px)}}
[data-wk="msg"]:nth-child(3n) [data-wk="bubble"]::after{animation-delay:-2.5s !important}
[data-wk="msg"]:nth-child(3n+1) [data-wk="bubble"]::after{animation-delay:-5s !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]::after{background:url("data:image/svg+xml;base64,") right 0 top 0/120px 16px repeat-x !important}
[data-wk="bubble"][data-kind="text"]::before{content:none !important}

/* 时间：时间后面跟一句永远不变的「（这里来过）」 */
[data-wk="time"] > span{background:none !important;border:none !important;box-shadow:none !important;color:#9AA0A4 !important;font-size:11.5px !important;letter-spacing:.2em !important;text-shadow:0 0 6px #fff !important}
[data-wk="time"] > span::after{content:"  （这里来过）" !important;opacity:.6 !important;letter-spacing:.1em !important}
/* 已读：一颗星星睁开眼；没读：闭着 */
[data-wk="meta"]{color:#9AA0A4 !important;font-size:10.5px !important;letter-spacing:.1em !important;display:inline-flex !important;align-items:center !important;gap:6px !important}
[data-wk="meta"]::before{content:"" !important;width:16px !important;height:16px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;filter:drop-shadow(0 0 3px #FFE45C) !important}
[data-wk="meta"][data-read="0"]::before{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;filter:none !important}
[data-wk="msg"][data-me="1"] [data-wk="meta"]{flex-direction:row-reverse !important}
[data-wk="msg"][data-last="0"] [data-wk="meta"]{display:none !important}
[data-run][data-last="1"] + [data-wk="cardmeta"]{display:block !important;font-size:10.5px !important;color:#9AA0A4 !important;padding:2px 0 0 62px !important}
[data-run][data-last="1"] + [data-wk="cardmeta"][data-me="1"]{text-align:right !important;padding:2px 62px 0 0 !important}
[data-wk="bubble"][data-kind="typing"]{background:#FFFCEB !important;border:none !important;border-radius:14px !important;box-shadow:0 0 14px 4px rgba(245,239,210,.5) !important}
[data-wk="bubble"][data-kind="typing"]::before,[data-wk="bubble"][data-kind="typing"]::after{content:none !important}
[data-wk="typingdot"]{background:#B79CFF !important}

/* 动描：一张旧拍立得的背面——白边、褪色的字，像照片背后写的 */
[data-wk="narr"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="narrink"],[data-wk="myactink"]{display:inline-block !important;background:#fff !important;border:none !important;border-radius:2px !important;box-shadow:0 0 0 6px #fff,0 6px 16px rgba(120,130,135,.2) !important;backdrop-filter:none !important;-webkit-backdrop-filter:none !important;color:#9CA2A6 !important;opacity:1 !important;font-style:italic !important;font-size:12.5px !important;line-height:1.75 !important;padding:6px 14px !important;margin:8px 0 !important;transform:rotate(-1deg) !important}
[data-wk="myactink"]{transform:rotate(1deg) !important;color:#7E7A92 !important}
/* 系统提示：梦里的告示 */
[data-wk="sysnote"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="sysnotelabel"]{display:none !important}
[data-wk="sysnotetext"]{background:transparent !important;border:none !important;color:#9AA0A4 !important;font-size:11px !important;font-style:normal !important;letter-spacing:.12em !important}
[data-wk="sysnotetext"]::before{content:"⟡ " !important;color:#FFE45C !important}
[data-wk="sysnotetext"]::after{content:" ⟡" !important;color:#FFE45C !important}
[data-wk="narrbar"]{background:rgba(255,255,255,.7) !important;border-top:1px solid #fff !important}
[data-wk="narrkind"]{border:1px solid #D5DADD !important;border-radius:999px !important;background:transparent !important;color:#9AA0A4 !important}
[data-wk="narrkind"][data-on="1"]{background:#D6DFE3 !important;color:#4A4E52 !important}

/* 底栏：同一层旧玻璃；左一颗粉星加号、雾色输入框、右边月亮发送、带星星的对话框回复 */
[data-wk="composer"]{background:rgba(255,255,255,.55) !important;backdrop-filter:blur(8px) !important;-webkit-backdrop-filter:blur(6px) !important;border-top:none !important;box-shadow:0 -1px 0 #fff,0 -4px 18px rgba(200,212,218,.35) !important;align-items:center !important;gap:8px !important}
[data-wk="chatinput"]{background:rgba(255,255,255,.7) !important;border:1px solid #fff !important;border-radius:14px !important;color:#4A4E52 !important}
[data-wk="chatinput"]::placeholder{color:#AEB4B8 !important}
[data-wk="chatplus"]{width:28px !important;min-width:28px !important;height:28px !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;border-radius:0 !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAzMCAzMCc+PGcgdHJhbnNmb3JtPSd0cmFuc2xhdGUoMyAzKSc+PHBhdGggdHJhbnNmb3JtPSdzY2FsZSgyLjQpJyBkPSdNNSAwIEw2LjIgMy42IEwxMCAzLjggTDcgNi4yIEw4IDEwIEw1IDcuOCBMMiAxMCBMMyA2LjIgTDAgMy44IEwzLjggMy42WicgZmlsbD0nI0ZGN0FDOCcvPjwvZz48L3N2Zz4=") center/contain no-repeat !important;filter:drop-shadow(0 0 4px #FF7AC8) !important}
[data-wk="chatplus"] svg{display:none !important}
[data-wk="send"]{width:36px !important;min-width:36px !important;height:36px !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;border-radius:0 !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;opacity:1 !important}
[data-wk="chatreply"]{width:40px !important;min-width:40px !important;height:34px !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;border-radius:0 !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="chatplus"] *,[data-wk="send"] *,[data-wk="chatreply"] *{opacity:0 !important}

/* 打电话那一屏：同一片褪色的梦，月亮更近 */
[data-wk="call"][data-video="0"]{background:radial-gradient(circle at 50% 20%,#FFFBE6 0 70px,rgba(255,250,224,.5) 76px,transparent 220px),url("data:image/svg+xml;base64,") 0 0/240px 300px,linear-gradient(180deg,#F6F5F0,#E3E8EA) !important}
[data-wk="calltitle"]{color:#4A4E52 !important;letter-spacing:.15em !important}
[data-wk="callavatar"]{border-radius:50% !important;box-shadow:0 0 0 5px #FFFCEB,0 0 40px 14px rgba(245,239,210,.7),12px -8px 0 10px rgba(245,239,210,.2) !important}
[data-wk="callbtns"] button > span:first-child{background:#FFFCEB !important;border-radius:50% !important;box-shadow:0 0 16px 4px rgba(245,239,210,.6) !important}
[data-wk="callbtns"] button > span:first-child svg{stroke:#4A4E52 !important}
[data-wk="callbtns"] button:nth-child(2) > span:first-child{background:#fff !important;box-shadow:inset 0 0 0 1.5px #FF7AC8,0 0 14px #FF7AC8 !important}
[data-wk="callbtns"] button:nth-child(2) > span:first-child svg{stroke:#FF7AC8 !important}
[data-wk="call"][data-video="0"] [data-wk="callbtns"] button > span:last-child{color:#4A4E52 !important}
[data-wk="callbubble"]{background:#FFFCEB !important;color:#4A4E52 !important;border:none !important;border-radius:14px !important}
[data-wk="callmsg"][data-me="1"] [data-wk="callbubble"]{background:#DCE5E9 !important;color:#3E4A52 !important}
[data-wk="callbubble"]::before,[data-wk="callbubble"]::after{content:none !important}
[data-wk="note"][data-part="callsum"]{display:block !important;margin:6px auto 0 !important;background:#fff !important;border:none !important;border-radius:2px !important;box-shadow:0 0 0 5px #fff !important;padding:8px 14px !important;color:#A39CBC !important;font-size:12px !important;font-style:italic !important;text-align:left !important}
[data-wk="noteink"]{color:#9AA0A4 !important}
[data-wk="callact"]{color:#B79CFF !important}

/* ───── 月下星路 · 第二批：卡片（形状不动；都是一张发光的月光卡，底下也跟着一串星星） ───── */
[data-wk="transfercard"],[data-wk="photocard"],[data-wk="geocard"] > [data-wk="card"],[data-wk="namecard"],[data-part="offlog"],[data-wk="callpill"] > [data-wk="block"],[data-wk="wxcard"],[data-wk="rpcard"]{position:relative !important;overflow:visible !important;background:rgba(255,255,255,.82) !important;border:none !important;border-radius:14px !important;box-shadow:inset 0 0 0 1.5px #fff,0 0 18px 4px rgba(255,248,226,.8) !important;color:#4A4E52 !important;margin-bottom:10px !important}
[data-wk="transfercard"]::after,[data-wk="photocard"]::after,[data-wk="wxcard"]::after,[data-wk="rpcard"]::after{content:"" !important;position:absolute !important;left:14px !important;right:14px !important;bottom:-12px !important;top:auto !important;width:auto !important;height:14px !important;background:url("data:image/svg+xml;base64,") 0 0/120px 16px repeat-x !important;border:none !important;box-shadow:none !important;pointer-events:none !important}
[data-wk="transfercard"] *,[data-wk="namecard"] *,[data-part="offlog"] *,[data-wk="geocard"] *,[data-wk="callpill"] *,[data-wk="photocard"] *,[data-wk="wxcard"] *{color:#4A4E52 !important;border-color:#E3E7E9 !important}
[data-wk="transferamount"],[data-wk="transfercur"]{color:#8C8460 !important}
[data-wk="transferrule"]{border:none !important;height:1px !important;background:#E3E7E9 !important}
[data-wk="transfernotch"]{display:none !important}
[data-wk="transferfoot"]{background:transparent !important;border-top:1px solid #E3E7E9 !important}
[data-wk="transferbtn"]{border-radius:999px !important}
[data-wk="transferbtn"][data-part="take"]{background:#FFF6CF !important;color:#4A4E52 !important;border:1px solid #E6CF7A !important}
[data-wk="transferbtn"][data-part="back"]{background:transparent !important;border:1px solid #D5DADD !important}
[data-wk="transferseal"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;border:none !important;box-shadow:none !important;width:36px !important;height:36px !important;font-size:0 !important;color:transparent !important;filter:drop-shadow(0 0 4px #FFE45C) !important}
[data-wk="transferseal"] *{opacity:0 !important}
[data-wk="transfercard"][data-status="returned"]{opacity:.5 !important}
/* 红包：一块冷灰玻璃，左边一轮小月亮；领完月亮暗下去 */
[data-wk="rpcard"]{background:linear-gradient(180deg,rgba(226,234,238,.95),rgba(208,219,225,.95)) !important;border:none !important;border-radius:14px !important;box-shadow:inset 0 0 0 1.5px #fff,0 0 16px 4px rgba(190,214,224,.7) !important;padding-left:54px !important}
[data-wk="rpcard"]::before{content:"" !important;position:absolute !important;left:12px !important;top:calc(50% - 17px) !important;width:34px !important;height:34px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;z-index:2 !important}
[data-wk="rpcard"] *{color:#3E4A52 !important}
[data-wk="rpflap"],[data-wk="rpseal"],[data-wk="rpcorner"]{display:none !important}
[data-wk="rpcard"][data-status="done"]{opacity:.6 !important}
[data-wk="rpcard"][data-status="done"]::before{filter:grayscale(1) !important}
[data-wk="rpenvelope"]{background:rgba(255,255,255,.82) !important;border:none !important;border-radius:14px !important;box-shadow:inset 0 0 0 1.5px #fff,0 0 18px 4px rgba(255,248,226,.8) !important;background:radial-gradient(circle at 50% 22%,#FFFCEB 0 50px,transparent 130px),linear-gradient(180deg,#F6F5F0,#E3E8EA) !important}
[data-wk="rpenvelope"] [data-wk="rparc"]{background:transparent !important;border:none !important}
[data-wk="rpenvelope"] *{color:#4A4E52 !important}
[data-wk="rpopenbtn"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;border:none !important;box-shadow:none !important;filter:drop-shadow(0 0 12px rgba(255,240,200,.9)) !important}
[data-wk="rpopenbtn"] *{opacity:0 !important}
[data-wk="rpamount"]{color:#8C8460 !important}
[data-wk="rpavatar"],[data-wk="rpavatar"] *{border-radius:50% !important}
[data-wk="rpavatar"]{box-shadow:0 0 0 3px #fff,0 0 18px 5px rgba(255,240,214,.9),6px -4px 0 5px rgba(190,205,212,.4) !important}
/* 照片：一张过曝的旧照片；语音跟气泡一样 */
[data-wk="photocard"]{padding:8px 8px 10px !important}
[data-wk="photoface"]{border-radius:6px !important;background:linear-gradient(180deg,#FBFAF5,#E6EBED) !important;border:none !important;box-shadow:inset 0 0 30px rgba(255,255,255,.9) !important}
[data-wk="photoface"] *,[data-wk="photohint"]{color:#9AA0A4 !important}
[data-wk="photoface"] svg{stroke:#9AA0A4 !important}
[data-wk="voice"][data-me]{background:rgba(255,255,255,.82) !important;border:none !important;border-radius:14px !important;box-shadow:inset 0 0 0 1.5px #fff,0 0 18px 4px rgba(255,248,226,.8) !important}
[data-wk="voice"][data-me="1"]{background:linear-gradient(180deg,rgba(226,234,238,.95),rgba(208,219,225,.95)) !important;border:none !important;border-radius:14px !important;box-shadow:inset 0 0 0 1.5px #fff,0 0 16px 4px rgba(190,214,224,.7) !important}
[data-wk="voice"] > *{background:transparent !important;border:none !important;box-shadow:none !important;color:#4A4E52 !important}
[data-wk="voicewave"] span{background:#B79CFF !important}
[data-wk="voice"][data-me="1"] [data-wk="voicewave"] span{background:#6FF2C8 !important}
/* 天气：太阳换成那轮月亮 */
[data-wk="wxcardsky"]{background:transparent !important}
[data-wk="wxcardsky"] > div:first-child{background:radial-gradient(circle,#FFF6CF 0 12px,rgba(255,246,207,.4) 14px,transparent 60%) !important}
[data-wk="wxcardsky"] svg{stroke:#9AA0A4 !important}
[data-wk="wxcardsky"] span[style*="999"],[data-wk="wxcardrain"]{background:rgba(230,235,237,.7) !important;border:none !important}
[data-wk="wxcardsay"]{background:rgba(246,245,240,.8) !important;border-top:1px solid #E3E7E9 !important}
[data-wk="wxcardsay"],[data-wk="wxcardsay"] *{color:#4A4E52 !important}
[data-wk="geopin"]{background:#FF7AC8 !important;box-shadow:0 0 0 2px #fff,0 0 8px #FF7AC8 !important}
[data-wk="geopinstem"]{background:#9AA0A4 !important}
[data-wk="namecard"] img{border-radius:50% !important;box-shadow:0 0 0 3px #fff,0 0 18px 5px rgba(255,240,214,.9),6px -4px 0 5px rgba(190,205,212,.4) !important}
[data-run][data-last="1"] + [data-wk="cardmeta"]::before{content:"" !important;display:inline-block !important;vertical-align:middle !important;width:14px !important;height:14px !important;margin:0 6px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="note"][data-part="pat"],[data-wk="note"][data-part="call"]{display:inline-block !important;border:none !important;background:rgba(255,255,255,.7) !important;border-radius:999px !important;padding:3px 14px !important;color:#9AA0A4 !important;box-shadow:0 0 10px rgba(255,255,255,.9) !important}
[data-wk="note"][data-part="call"] svg{stroke:#9AA0A4 !important}
[data-wk="offlogtitle"]{letter-spacing:.2em !important;color:#4A4E52 !important}
[data-wk="offlogopen"],[data-wk="offlogredo"],[data-wk="offlogundo"],[data-wk="offlogrestore"]{color:#8C8460 !important}
[data-wk="offlogtranscript"]{border-top:1px solid #E3E7E9 !important}
/* 加号面板：一颗颗发光的小圆窗 */
[data-wk="chatpanel"]{background:rgba(246,245,240,.9) !important;border-top:1px solid #fff !important}
[data-wk="chattoolicon"]{background:rgba(255,255,255,.85) !important;border:none !important;border-radius:50% !important;box-shadow:inset 0 0 0 1.5px #fff,0 0 14px 3px rgba(255,248,226,.9) !important}
[data-wk="chattoolglyph"],[data-wk="chattoolglyph"] svg{stroke:#4A4E52 !important;color:#4A4E52 !important}
[data-wk="chattoollabel"]{color:#9AA0A4 !important}
